<script setup lang="ts">
import { mapStyle, addMapBranding } from '@/services/map-style'
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue'
import type {Trip,ItineraryItem} from '@/types'
import type * as MapLibre from 'maplibre-gl'
import {PH_BOUNDS,PH_NAVIGATION,inPhilippines} from '@/services/philippines'
import {validCoordinates} from '@/types/destination'
import {directions} from '@/composables/tripPlanner'
import 'maplibre-gl/dist/maplibre-gl.css'
const props=defineProps<{trip:Trip;items:ItineraryItem[]}>()
const emit=defineEmits<{editDestination:[];edit:[ItineraryItem]}>()
const container=ref<HTMLDivElement>(),error=ref(''),loading=ref(true),selected=ref('')
const points=computed(()=>[
 ...(validCoordinates(props.trip.destination_latitude,props.trip.destination_longitude)?[{id:'destination',name:props.trip.destination||'Trip destination',lat:props.trip.destination_latitude!,lng:props.trip.destination_longitude!}]:[]),
 ...props.items.filter(i=>validCoordinates(i.latitude??i.location?.latitude,i.longitude??i.location?.longitude)).map(i=>({id:i.id,name:i.title,lat:(i.latitude??i.location?.latitude)!,lng:(i.longitude??i.location?.longitude)!}))
])
const unmapped=computed(()=>props.items.filter(i=>i.location_name&&!validCoordinates(i.latitude??i.location?.latitude,i.longitude??i.location?.longitude)))
let map:MapLibre.Map|undefined,lib:typeof MapLibre.default,markers:MapLibre.Marker[]=[],disposed=false,timeout:ReturnType<typeof setTimeout>
function focus(id:string){selected.value=id;const p=points.value.find(p=>p.id===id);if(p)map?.flyTo({center:[p.lng,p.lat],zoom:12,duration:window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:500})}
function draw(){if(!map)return;if(!points.value.length)map.fitBounds(PH_BOUNDS,{padding:24,duration:0});markers.forEach(m=>m.remove());markers=[];for(const p of points.value){const button=document.createElement('button');button.type='button';button.className='trip-map-pin';button.textContent=String(points.value.indexOf(p)+1);button.setAttribute('aria-label','Show '+p.name);button.addEventListener('click',()=>focus(p.id));markers.push(new lib.Marker({element:button}).setLngLat([p.lng,p.lat]).addTo(map))}if(points.value.length>1){const bounds=new lib.LngLatBounds();points.value.forEach(p=>bounds.extend([p.lng,p.lat]));map.fitBounds(bounds,{padding:70,maxZoom:13,duration:0})}else if(points.value[0])map.jumpTo({center:[points.value[0].lng,points.value[0].lat],zoom:10})}
onMounted(async()=>{try{lib=(await import('maplibre-gl')).default;if(disposed)return;map=new lib.Map({container:container.value!,center:[122,12],zoom:4,maxBounds:points.value.every(p=>inPhilippines(p.lat,p.lng))?PH_NAVIGATION:undefined,style:mapStyle()});addMapBranding(map);map.addControl(new lib.NavigationControl({showCompass:false}));map.on('load',()=>{loading.value=false;clearTimeout(timeout)});map.on('error',()=>{loading.value=false;error.value='Map tiles are unavailable. Your saved places are listed below.'});timeout=setTimeout(()=>{loading.value=false;error.value='The map is taking longer than expected. Your saved places remain available.'},12000);draw()}catch{loading.value=false;error.value='The map cannot display in this browser. Your saved places remain available.'}})
watch(points,draw)
onBeforeUnmount(()=>{disposed=true;clearTimeout(timeout);markers.forEach(m=>m.remove());map?.remove()})
</script>
<template><section class="trip-map-view"><header><p class="eyebrow">Places in your itinerary</p><h2>A sense of place.</h2><p class="map-help">Saved pins only. No routes or travel-time estimates.</p></header><div ref="container" class="trip-map-canvas" aria-label="Saved itinerary places map" /><p v-if="loading" role="status" class="map-help">Opening the map…</p><p v-if="error" role="status" class="map-help">{{error}}</p><p v-if="!points.length" class="map-help">No saved pins yet. The Philippines view is not your current location.</p><div class="map-place-list"><button v-for="(p,index) in points" :key="p.id" :aria-pressed="selected===p.id" @click="focus(p.id)"><span>{{p.id==='destination'?'Destination':'Place '+(index+1)}}</span><strong>{{p.name}}</strong><small>Saved location</small></button></div><button @click="emit('editDestination')">{{points.some(p=>p.id==='destination')?'Edit destination pin':'Choose a destination pin'}}</button><div v-if="unmapped.length" class="unmapped"><h3>Places to explore</h3><p class="map-help">Names without coordinates stay off the map.</p><div v-for="item in unmapped" :key="item.id"><span>{{item.title}}<small>{{item.location_name}}</small></span><a v-if="directions(item)" :href="directions(item)!" target="_blank" rel="noopener noreferrer">View place ↗</a></div></div></section></template>
<style scoped>.trip-map-view header{margin-bottom:18px}.trip-map-view h2{margin:6px 0;font-size:29px}.map-help{font-size:13px;color:#7d715f;line-height:1.6;margin:10px 0}.trip-map-canvas{height:clamp(260px,45dvh,500px);background:#e5e9df;border:1px solid #d3d8c9;border-radius:12px;touch-action:none;overflow:hidden}.trip-map-canvas :deep(.maplibregl-ctrl-group button){width:44px;height:44px}.trip-map-canvas :deep(.trip-map-pin){width:44px;height:44px;padding:0;border-radius:50%;border:3px solid #fffaf0;color:#fffaf0;background:#74283c;font-size:20px;box-shadow:0 2px 7px #49352133}.map-place-list{display:grid;gap:8px;margin:14px 0;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}.map-place-list button{display:grid;text-align:left;justify-content:start;gap:4px;padding:14px}.map-place-list button[aria-pressed=true]{background:#e8ede2}.map-place-list span{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#768264}.map-place-list strong{font-weight:500;overflow-wrap:anywhere}.map-place-list small{font-size:12px;color:#81735f}.unmapped{margin-top:24px}.unmapped>div{display:flex;align-items:center;gap:12px;justify-content:space-between;padding:12px 0;border-bottom:1px solid #ded4c3}.unmapped span{min-width:0;overflow-wrap:anywhere;font-size:14px}.unmapped small{display:block;color:#7b806a;margin-top:4px}.unmapped a{flex-shrink:0;color:#74283c;min-height:44px;display:flex;align-items:center;font-size:13px}@media(max-width:600px){.map-place-list{grid-template-columns:1fr}}</style>
